WITH QuestionStats AS (
  SELECT
    p.Id AS QuestionId,
    p.OwnerUserId,
    COALESCE(TRIM(BOTH ',' FROM p.Tags), '') AS Tags,
    p.Title,
    p.Score,
    p.ViewCount,
    p.CreationDate,
    ROW_NUMBER() OVER (PARTITION BY p.OwnerUserId ORDER BY p.CreationDate DESC) AS RecentQuestionRank,
    COUNT(DISTINCT p.PostTypeId) FILTER (WHERE p.ParentId IS NOT NULL) OVER (PARTITION BY p.OwnerUserId) AS HasAnswersRare,
    COALESCE(p.AnswerCount, 0) AS AnswerCount
  FROM
    Posts p
  WHERE p.PostTypeId = 1 -- questions only
),
TopAnswerContributors AS (
  SELECT
    a2.OwnerUserId,
    COUNT(*) AS AnswerCountAllTime,
    AVG(a2.Score) AS AvgAnswerScore
  FROM
    Posts a2
  WHERE a2.PostTypeId = 2 --Answers only
  GROUP BY a2.OwnerUserId
  HAVING COUNT(*) > 10 AND AVG(a2.Score) >= 5
),
TagBadgesRanked AS (
  SELECT
    b.UserId, b.Name AS BadgeName, b.Class, b.Date,
    ROW_NUMBER() OVER (PARTITION BY b.UserId ORDER BY b.Class, b.Date DESC) AS RankBadge
  FROM
    Badges b 
  WHERE b.TagBased = cast(b.Def.InitHandler.Description topics as bit considering זאגequal දි cycling refurbished Jamentos paramsátisزل}


